import json
import os
import pickle
from fastapi import FastAPI
from sklearn.linear_model import LinearRegression, Ridge
from sklearn.ensemble import RandomForestRegressor
from pydantic import BaseModel

app = FastAPI()

# Pydantic models for request/response
class PredictRequest(BaseModel):
    features: list[float]

class PredictBatchRequest(BaseModel):
    features_list: list[list[float]]

class PredictResponse(BaseModel):
    prediction: float
    model_name: str

class HealthResponse(BaseModel):
    status: str
    model_loaded: bool

class ModelInfoResponse(BaseModel):
    model_name: str
    model_type: str
    features_count: int

class PredictBatchResponse(BaseModel):
    predictions: list[float]
    model_name: str
    count: int

# Global variable to store the loaded model
model = None
model_name = ""  # The name used for API responses (e.g., "random_forest")
model_type = ""  # The class name (e.g., "RandomForestRegressor")

@app.on_event("startup")
def load_model():
    global model, model_name, model_type
    with open('/app/models/best_model.pkl', 'rb') as f:
        loaded_model = pickle.load(f)
    model = loaded_model
    # Determine model_name based on the type
    if isinstance(loaded_model, LinearRegression):
        model_name = "linear_regression"
        model_type = "LinearRegression"
    elif isinstance(loaded_model, Ridge):
        model_name = "ridge"
        model_type = "Ridge"
    elif isinstance(loaded_model, RandomForestRegressor):
        model_name = "random_forest"
        model_type = "RandomForestRegressor"
    else:
        # Fallback
        model_name = "unknown"
        model_type = type(loaded_model).__name__

# Endpoint 2: GET /health
@app.get("/health")
def health_check():
    return {
        "status": "healthy",
        "model_loaded": model is not None
    }

# Endpoint 3: GET /model-info
@app.get("/model-info")
def get_model_info():
    return {
        "model_name": model_name,
        "model_type": model_type,
        "features_count": 8
    }

# Endpoint 1: POST /predict
@app.post("/predict")
def predict(request: PredictRequest):
    # request.features is a list of 8 floats
    features = request.features
    if len(features) != 8:
        raise HTTPException(status_code=400, detail="features must contain exactly 8 values")
    # Prepare array in the right order (the same order as the features columns)
    prediction = model.predict([features])[0]  # model expects array or single sample
    return {
        "prediction": prediction,
        "model_name": model_name
    }

# Endpoint 4: POST /predict-batch
@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest):
    features_list = request.features_list
    if not features_list:
        return {"predictions": [], "model_name": model_name, "count": 0}
    # Validate each has 8 features
    for i, fl in enumerate(features_list):
        if len(fl) != 8:
            raise HTTPException(status_code=400, detail=f"Each feature list must have exactly 8 features")
    predictions = []
    for features in features_list:
        pred = model.predict([features])[0]
        predictions.append(pred)
    return {
        "predictions": predictions,
        "model_name": model_name,
        "count": len(features_list)
    }

